import { describe, expect, it } from "vitest";

import { runScenario } from "./claim-office.js";

/**
 * Test list for the MHPCO Claim Office kata.
 *
 * Observable contract chosen for rejection cases (stated explicitly, as the
 * specification defines the CLI-level outcome but not the internal mechanism):
 * the domain layer throws an `Error` whose message describes the problem, and
 * the CLI adapter catches it, writes the message to stderr and exits non-zero
 * without writing `results` to stdout. Tests below assert `toThrow()` at the
 * domain level and the exit-code / stream contract at the CLI level.
 */

describe("MHPCO Claim Office", () => {
  // --- Quote: processing fee and the simplest possible policy ---------------
  it("quote for an empty item list -- premium 5 G (processing fee only)", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(results).toEqual([{ premium: 5 }]);
  });

  // --- Quote: main item base premiums (parallel catalogue: one test each) ---
  it("quote for a single sword -- premium 115 G (100 base + 10 first insurance + 5 fee)", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });

    expect(results).toEqual([{ premium: 115 }]);
  });
  it.todo("quote for a single amulet -- premium 71 G (60 base + 6 first insurance + 5 fee)");
  it.todo("quote for a single staff -- premium 93 G (80 base + 8 first insurance + 5 fee)");
  it.todo("quote for a single potion -- premium 49 G (40 base + 4 first insurance + 5 fee)");

  // --- Quote: component base premiums (parallel catalogue) -----------------
  it.todo("quote for a single rune -- premium 32 G (25 base + 2.5 first insurance + 5 fee, rounded up)");
  it.todo("quote for a single moonstone -- premium 32 G (25 base + 2.5 first insurance + 5 fee, rounded up)");

  // --- Quote: unknown item type is rejected --------------------------------
  it.todo("quote with an unknown item type 'broomstick' -- throws an error describing the unknown type");

  // --- Building block of 3 alike components (spec examples verbatim) -------
  it.todo("base premium for 2 runes -- 50 G (no block)");
  it.todo("base premium for 3 runes -- 60 G (block applies)");
  it.todo("base premium for 4 runes -- 100 G (no block -- block requires exactly 3)");
  it.todo("base premium for 7 runes -- 175 G (no block -- block requires exactly 3)");

  // --- 'Alike' means same type, not same family (clarifying question) ------
  it.todo("base premium for 2 runes + 1 moonstone -- 75 G (no block: different types)");
  it.todo("base premium for 3 runes + 3 moonstones -- 120 G (two separate blocks)");

  // --- Item-specific modifiers --------------------------------------------
  it.todo("cursed sword adds a 50 % surcharge on that item's base premium -- 100 G base becomes 150 G");
  it.todo("sword with enchantment 5 adds a 30 % high-enchantment surcharge -- 100 G base becomes 130 G");
  it.todo("sword with enchantment 4 gets no high-enchantment surcharge -- base premium stays 100 G");
  it.todo("cursed sword with enchantment 5 gets both surcharges -- 100 G base becomes 180 G");

  // --- Modifier scope on multi-item policies (clarifying question) ---------
  it.todo("cursed sword + plain amulet -- item surcharge is 50 G (50 % of the cursed sword only), policy base 160 G becomes 210 G before policy modifiers and fee");

  // --- Policy-wide modifiers ----------------------------------------------
  it.todo("customer with exactly 2 years with MHPCO -- 20 % loyalty discount applies to the policy base premium");
  it.todo("customer with 1 year with MHPCO -- no loyalty discount");
  it.todo("first insurance adds a 10 % surcharge on the policy base premium");
  it.todo("each contract after the first gets a 15 % follow-up discount on the policy base premium");
  it.todo("the first quote in a scenario gets no follow-up discount");
  it.todo("the first insurance surcharge still applies on a follow-up contract (each quoted item is a first insurance)");

  // --- Rounding in the MHPCO's favour --------------------------------------
  it.todo("a premium calculation yielding 197.5 G -- final premium 198 G (rounded up)");
  it.todo("intermediate premium amounts are kept as fractions -- only the final premium is rounded");

  // --- Quote integration examples -----------------------------------------
  it.todo("newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 -- premium 165 G");
  it.todo("3-year customer's second quote, cursed steel sword enchantment 7 -- premium 160 G");

  // --- Insurance sum and cap ----------------------------------------------
  it.todo("policy covering a sword and an amulet -- insurance sum 1600 G, cap 3200 G");
  it.todo("policy covering two swords -- insurance sum 2000 G, cap 4000 G");
  it.todo("policy covering a sword and 3 runes -- insurance sum 1750 G, cap 3500 G (block discount affects the premium only)");
  it.todo("cursed sword with premium 165 G -- cap 2000 G (premium modifiers do not raise the cap)");

  // --- Claim: standard reimbursement and deductible ------------------------
  it.todo("claim on a steel sword enchantment 3, damage 500 G -- payout 400 G (full reimbursement minus 100 G deductible)");
  it.todo("claim on a rune (no enchantment, no material), damage 200 G -- payout 100 G (no special clause applies)");
  it.todo("claim whose damage is below the deductible -- payout 0 G (the deductible never produces a negative payout)");

  // --- Claim: special clauses ---------------------------------------------
  it.todo("claim on a steel sword enchantment 9, damage 1000 G -- payout 400 G (50 % high-enchantment clause first, then deductible)");
  it.todo("claim on a dragon-material sword enchantment 5, damage 800 G -- payout 700 G (full reimbursement, then deductible)");
  it.todo("claim on a dragon-material sword enchantment 9, damage 1000 G -- payout 400 G (both clauses apply; the 50 % rule wins, then deductible)");
  it.todo("claim on a dragon-material sword with exactly enchantment 8, damage 1000 G -- payout 400 G (threshold is inclusive)");
  it.todo("claim on a steel sword enchantment 7, damage 1000 G -- payout 900 G (below the high-enchantment threshold)");

  // --- Claim: deductible is per damage event -------------------------------
  it.todo("one incident damaging a sword (500 G) and an amulet (300 G) -- payout 600 G (100 G deductible per damaged item)");
  it.todo("one incident damaging two insured swords -- each damage entry gets its own deductible");

  // --- Claim: cap exhaustion across successive claims -----------------------
  it.todo("sword policy (cap 2000 G), first claim of 1500 G -- payout 1400 G, remainingCap 600 G");
  it.todo("sword policy (cap 2000 G), second claim of 1500 G after the first -- payout 600 G, remainingCap 0 G (reduced to the remaining cap)");

  // --- Claim: rounding in the MHPCO's favour --------------------------------
  it.todo("a payout calculation yielding 350.5 G -- final payout 350 G (rounded down)");

  // --- Claim: rejection cases ----------------------------------------------
  it.todo("claim naming an item type not covered by the policy (amulet damaged, only a sword insured) -- throws an error");
  it.todo("claim naming an unknown item type -- throws an error");
  it.todo("claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) -- throws an error");
  it.todo("claim with a negative damage amount (-200) -- throws an error");
  it.todo("claim referencing a policy step index that is not a quote -- throws an error");

  // --- CLI adapter ---------------------------------------------------------
  it.todo("CLI reads the schema example from stdin and writes {results:[{premium},{payout,remainingCap}]} to stdout with exit code 0");
  it.todo("CLI processes steps sequentially so a later claim uses the policy created by the referenced quote step");
  it.todo("CLI on an unknown quote item type -- exits non-zero, writes an error description to stderr, writes no results to stdout");
  it.todo("CLI on an invalid claim -- exits non-zero and writes an error description to stderr");
});

