const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();

  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }

  return counts;
}

function basePremiumOfAlikeItems(item: Item, count: number): number {
  if (count === BLOCK_SIZE) {
    return BLOCK_BASE_PREMIUM;
  }

  return count * basePremiumOf(item);
}

function policyBasePremiumOf(items: Item[]): number {
  let total = 0;

  for (const [type, count] of countByType(items)) {
    total += basePremiumOfAlikeItems({ type }, count);
  }

  return total;
}

function quotePremium(items: Item[]): number {
  const policyBasePremium = policyBasePremiumOf(items);
  const surcharges = policyBasePremium * FIRST_INSURANCE_SURCHARGE;

  return Math.ceil(policyBasePremium + surcharges + PROCESSING_FEE);
}

