export type StepResult = QuoteResult;

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

function basePremiumOf(item: Item): number {
  const basePremium = BASE_PREMIUMS[item.type];

  if (basePremium === undefined) {
    throw new Error(`Unknown item type: ${item.type}`);
  }

  return basePremium;
}

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();

  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }

  return counts;
}

function basePremiumOfAlikeItems(item: Item, count: number): number {
  if (count === BLOCK_SIZE) {
    return BLOCK_BASE_PREMIUM;
  }

  return count * basePremiumOf(item);
}

