const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const CAP_MULTIPLIER = 2;
const DEDUCTIBLE = 100;

function insuranceValueOf(type: string): number {
  const value = INSURANCE_VALUES[type];

  if (value === undefined) {
    throw new Error(`Unknown item type: ${type}`);
  }

  return value;
}

function insuranceSumOf(items: Item[]): number {
  return items.reduce((sum, item) => sum + insuranceValueOf(item.type), 0);
}

interface Policy {
  items: Item[];
  remainingCap: number;
}

function payoutForDamage(damage: Damage): number {
  return Math.max(0, damage.amount - DEDUCTIBLE);
}

function settleClaim(policy: Policy, incident: Incident): ClaimResult {
  const desired = incident.damages.reduce(
    (total, damage) => total + payoutForDamage(damage),
    0,
  );
  const payout = Math.floor(Math.min(desired, policy.remainingCap));

  policy.remainingCap -= payout;

  return { payout, remainingCap: policy.remainingCap };
